const smoney=(n,d)=>(n<0?'-':'+')+money(Math.abs(n),d);
/* quantities — same grouping as money(), without the currency mark */
const qty=(n,d)=>Number(n||0).toLocaleString('en-US',
  {minimumFractionDigits:d==null?2:d,maximumFractionDigits:d==null?2:d});
function compact(n){if(n===0)return '$0';if(!n)return '—';
  return n>=1e12?'$'+(n/1e12).toFixed(2)+'T':n>=1e9?'$'+(n/1e9).toFixed(1)+'B':n>=1e6?'$'+(n/1e6).toFixed(1)+'M':n>=1e3?'$'+(n/1e3).toFixed(1)+'K':money(n,0)}
const dp=p=>p>=10000?0:p>=1000?1:p>=1?2:4;
