const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const cssv=v=>getComputedStyle(document.documentElement).getPropertyValue(v).trim();
/* zero is neither up nor down; null means "not loaded yet" */
const dir=c=>c==null?'':c>0?'up':c<0?'dn':'';
const pctS=c=>c==null?'—':(c>0?'+':'')+c.toFixed(2)+'%';
function rgba(c,a){if(c.startsWith('#')){const n=parseInt(c.slice(1),16);return`rgba(${n>>16&255},${n>>8&255},${n&255},${a})`}return c}
function hash(s){let h=2166136261;for(const c of String(s))h=(h^c.charCodeAt(0))*16777619>>>0;return h}
function series(key,last,tf){
  const n={'1D':120,'1W':150,'1M':180,'3M':200,'1Y':240,'5Y':280}[tf]||120;
  const vol={'1D':.014,'1W':.03,'1M':.06,'3M':.09,'1Y':.16,'5Y':.3}[tf]||.02;
  let sd=hash(key+tf),out=[],p=last*(1-vol*.45);
  const rnd=()=>{sd=(sd*1664525+1013904223)>>>0;return sd/4294967296};
  for(let i=0;i<n;i++){p*=1+(rnd()-.487)*vol*.34;out.push(p)}
  const k=last/out[out.length-1];
  return out.map((v,i)=>v*(1+(k-1)*Math.pow(i/(n-1),1.6)));
}
function cdParts(iso){
  const ms=new Date(iso)-new Date();
  if(!(ms>0))return null;
  return{d:Math.floor(ms/864e5),h:Math.floor(ms/36e5)%24,m:Math.floor(ms/6e4)%60,s:Math.floor(ms/1e3)%60};
}
function cdShort(iso){const p=cdParts(iso);if(!p)return 'Closed';
  return p.d>0?`${p.d}d ${String(p.h).padStart(2,'0')}h`:`${String(p.h).padStart(2,'0')}h ${String(p.m).padStart(2,'0')}m`}
