    ctx.beginPath();ctx.roundRect(cw+4,ly-4,8,8,2);
    ctx.fillStyle=silverGrad(ctx,cw+2,ly-5,cw+12,ly+5,i,n,RING_BLUES);ctx.fill();
    const lg=ctx.createLinearGradient(cw+4,ly-4,cw+12,ly+4);
    lg.addColorStop(0,'rgba(255,255,255,.22)');lg.addColorStop(1,'rgba(255,255,255,0)');
    ctx.fillStyle=lg;ctx.fill();
