/* line chart with a silver stroke — axis labels, no gridlines */
function drawSilverLine(cv,data,opt){
  opt=opt||{};
  const f=fitCanvas(cv);if(!f)return;const{ctx,w,h}=f;
  if(!data||data.length<2)return;
  const padT=12,padB=8,padL=10,padR=52;
  const pw=w-padL-padR,ph=h-padT-padB;
  let lo=Math.min(...data),hi=Math.max(...data);
  if(lo===hi){lo-=1;hi+=1}
  const rg=hi-lo;
  const X=i=>padL+i*pw/(data.length-1),Y=v=>padT+ph-((v-lo)/rg)*ph;
  const T=axisTicks(lo,hi,4);
  ctx.strokeStyle=cssv('--line');ctx.lineWidth=1;
  ctx.fillStyle=cssv('--mute');ctx.font='500 10px "Open Sauce Sans",sans-serif';
  ctx.textAlign='left';ctx.textBaseline='middle';
  T.v.forEach(v=>{const y=Y(v);
    ctx.beginPath();ctx.moveTo(padL+pw,y);ctx.lineTo(padL+pw+4,y);ctx.stroke();
    ctx.fillText(opt.fmt?opt.fmt(v):axisFmt(v,T.step),padL+pw+8,y)});
  const fg=ctx.createLinearGradient(0,padT,0,padT+ph);
  fg.addColorStop(0,'rgba(228,230,236,.22)');fg.addColorStop(1,'rgba(228,230,236,0)');
  ctx.beginPath();ctx.moveTo(X(0),Y(data[0]));
  data.forEach((v,i)=>ctx.lineTo(X(i),Y(v)));
  ctx.lineTo(X(data.length-1),padT+ph);ctx.lineTo(X(0),padT+ph);ctx.closePath();
  ctx.fillStyle=fg;ctx.fill();
  if(lo<0&&hi>0){ctx.save();ctx.setLineDash([2,4]);ctx.strokeStyle=cssv('--line-2');
    ctx.beginPath();ctx.moveTo(padL,Y(0));ctx.lineTo(padL+pw,Y(0));ctx.stroke();ctx.restore()}
  const sg=ctx.createLinearGradient(padL,0,padL+pw,0);
  sg.addColorStop(0,'rgba(136,138,149,.85)');
  sg.addColorStop(.55,'rgba(234,235,240,1)');
  sg.addColorStop(1,'rgba(170,172,182,.95)');
  ctx.beginPath();data.forEach((v,i)=>i?ctx.lineTo(X(i),Y(v)):ctx.moveTo(X(i),Y(v)));
  ctx.strokeStyle=sg;ctx.lineWidth=1.6;ctx.lineJoin='round';ctx.stroke();
  const lx=X(data.length-1),ly=Y(data[data.length-1]);
  ctx.fillStyle='#E9EAEF';ctx.beginPath();ctx.arc(lx,ly,2.6,0,7);ctx.fill();
}
function drawHBars(cv,items){
  const F=fitCanvas(cv);if(!F)return;const{ctx,w,h}=F;
  if(!items.length){ctx.fillStyle=cssv('--mute');ctx.textAlign='center';
    ctx.textBaseline='middle';ctx.fillText('No positions',w/2,h/2);return}
  const padL=76,padR=118,padB=18,x0=padL,x1=w-padR;
  const mx=Math.max(...items.map(i=>i.v),1);
  barScale(ctx,x0,x1,2,h-padB,0,mx,(v,st)=>axisFmt(v,st));
  const rowH=Math.min(30,(h-padB-4)/items.length),bh=Math.min(14,rowH-9);
  const acc=cssv('--acc');
  items.forEach((it,i)=>{
    const y=4+i*rowH+(rowH-bh)/2-1,bw=it.v/mx*(x1-x0);
    const g=ctx.createLinearGradient(x0,0,x0+bw,0);
    g.addColorStop(0,rgba(acc,.5));g.addColorStop(1,rgba(acc,1));
    ctx.fillStyle=g;ctx.fillRect(x0,y,Math.max(bw,1),bh);
    ctx.fillStyle=cssv('--ink-2');ctx.textAlign='right';ctx.textBaseline='middle';
    ctx.fillText(it.k,padL-10,y+bh/2);
    ctx.textAlign='left';ctx.fillStyle=cssv('--ink');
    ctx.fillText(compact(it.v),x0+bw+8,y+bh/2);
    ctx.fillStyle=cssv('--mute');ctx.fillText(it.p.toFixed(1)+'%',x0+bw+8+50,y+bh/2);
  });
  ctx.strokeStyle=cssv('--line-2');ctx.lineWidth=1;
  ctx.beginPath();ctx.moveTo(x0,2);ctx.lineTo(x0,h-padB);ctx.stroke();
}
